def magic_square_test(matrix):
    # Calculate the sum of the first row to use as a reference
    ref_sum = sum(matrix[0])

    # Check if all rows have the same sum
    for row in matrix:
        if sum(row) != ref_sum:
            return False

    # Check if all columns have the same sum
    for col in range(len(matrix[0])):
        if sum(matrix[row][col] for row in range(len(matrix))) != ref_sum:
            return False

    # Check if the main diagonal has the same sum
    if sum(matrix[i][i] for i in range(len(matrix))) != ref_sum:
        return False

    # Check if the secondary diagonal has the same sum
    if sum(matrix[i][len(matrix)-1-i] for i in range(len(matrix))) != ref_sum:
        return False

    return True
