def max_sum(arr):
    n = len(arr)
    # Initialize the dp array to store the maximum sum up to each index
    dp = [0] * n

    # Fill the dp array from left to right
    for i in range(1, n):
        dp[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                dp[i] = max(dp[i], dp[j] + arr[i])

    # Fill the dp array from right to left
    for i in range(n-2, -1, -1):
        dp[i] = max(dp[i], arr[i])
        for j in range(i+1, n):
            if arr[j] > arr[i]:
                dp[i] = max(dp[i], dp[j] + arr[i])

    # The maximum sum will be the maximum value in the dp array
    return max(dp)

