    # Initialize the dp array with zeros
    dp = [[0 for _ in range(n)] for _ in range(n)]

    # Fill the dp array with the costs of the matrix
    for i in range(n):
        for j in range(n):
            dp[i][j] = matrix[i][j]

    # Calculate the maximum average path
    max_avg = float('-inf')
    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                avg = dp[i][j] / 1
            elif i == 0:
                avg = dp[i][j] / (j + 1)
            elif j == 0:
                avg = dp[i][j] / (i + 1)
            else:
